#!/usr/bin/env node
/**
 * Add the runtime permissions the app needs to the generated Android manifest.
 *
 * Why this exists: `apps/mobile/android/` is a build artifact, regenerated by
 * `cap add android` on every CI run, so there is no committed manifest to edit.
 * And `@capacitor/geolocation` ships a deliberately EMPTY AndroidManifest — its
 * README states the *app* must declare the location permissions itself. Nothing
 * in the default pipeline does that, so the APK built fine, installed fine, and
 * then could not so much as ask for GPS: the one feature the product exists for.
 *
 * That precedent is why POST_NOTIFICATIONS is declared here too. Today
 * `@capacitor/local-notifications` happens to declare it in its own manifest and
 * the merger folds it in — but "happens to" is exactly the assumption that cost
 * this project a GPS-less APK once already, and a plugin bump is all it takes to
 * change. Declaring it in the app costs a merged duplicate and nothing else.
 *
 * Idempotent, and fails loudly rather than silently producing a crippled APK.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const manifestPath = resolve(
  here,
  '..',
  join('android', 'app', 'src', 'main', 'AndroidManifest.xml'),
);

/** Permission, and the reason it is here — so a future reader can judge removals. */
const REQUIRED_PERMISSIONS = [
  ['android.permission.ACCESS_COARSE_LOCATION', 'geofence check-in (coarse fallback)'],
  ['android.permission.ACCESS_FINE_LOCATION', 'geofence check-in (GPS accuracy)'],
  ['android.permission.POST_NOTIFICATIONS', 'check-out reminders (Android 13+ runtime grant)'],
];

/**
 * Not declared as a hard `<uses-feature required="true">`: that would hide the
 * app on Play from tablets and other devices without GPS hardware, and an admin
 * who only ever opens the export screen has no need of it.
 */
const OPTIONAL_FEATURES = [['android.hardware.location.gps', 'false']];

let xml;
try {
  xml = readFileSync(manifestPath, 'utf8');
} catch (error) {
  console.error(`\nCannot read the Android manifest at:\n  ${manifestPath}\n`);
  console.error(
    'Run `npx cap add android` first — the native project is generated, not committed.',
  );
  console.error(`\nUnderlying error: ${error.message}\n`);
  process.exit(1);
}

const additions = [];

for (const [permission, reason] of REQUIRED_PERMISSIONS) {
  if (xml.includes(`android:name="${permission}"`)) continue;
  additions.push(`    <uses-permission android:name="${permission}" /> <!-- ${reason} -->`);
}

for (const [feature, required] of OPTIONAL_FEATURES) {
  if (xml.includes(`android:name="${feature}"`)) continue;
  additions.push(`    <uses-feature android:name="${feature}" android:required="${required}" />`);
}

if (additions.length === 0) {
  console.log('Android permissions already present — nothing to do.');
  process.exit(0);
}

// Insert before the closing </manifest>, which is where uses-permission belongs
// (a direct child of <manifest>, outside <application>).
const closing = xml.lastIndexOf('</manifest>');
if (closing === -1) {
  console.error(`\nNo closing </manifest> tag in ${manifestPath} — refusing to guess.\n`);
  process.exit(1);
}

const patched = `${xml.slice(0, closing)}\n${additions.join('\n')}\n\n${xml.slice(closing)}`;
writeFileSync(manifestPath, patched);

console.log(
  `Added ${additions.length} entr${additions.length === 1 ? 'y' : 'ies'} to the manifest:`,
);
for (const line of additions) console.log(`  ${line.trim()}`);
